arguments.command:
cd /tmp/sv-7c23d2495e3d44f3bd18585074abaa76/simple-solution && dotnet list package --format json 2>/dev/null | python3 -c "import sys,json; data=json.load(sys.stdin); json.dump(data,open('after-cpm-packages.json','w'),indent=2)" && python3 -c "
import json
b=json.load(open('baseline-packages.json'))
a=json.load(open('after-cpm-packages.json'))
def pkgs(d):
    r={}
    for p in d['projects']:
        for f in p['frameworks']:
            for pkg in f.get('topLevelPackages',[]):
                r[(p['path'].split('/')[-2],pkg['id'])]=pkg['resolvedVersion']
    return r
bp,ap=pkgs(b),pkgs(a)
if bp==ap: print('All packages resolve identically.')
else:
    for k in set(list(bp.keys())+list(ap.keys())):
        if bp.get(k)!=ap.get(k): print(f'DIFF {k}: {bp.get(k)} -> {ap.get(k)}')
"

